def bitmask_to_char(bits: Iterable[int]) -> int:
    """Convert sorted bit indices to the ASCII value (7-bit mask)."""
    mask = 0
    for b in bits:
        mask |= 1 << b
    return mask


@lru_cache(maxsize=None)
def dfs(
    idx: int,
    c0: int,
    c1: int,
    c2: int,
    c3: int,
    c4: int,
    c5: int,
    c6: int,
    c7: int,
    prev: int,
    current_mask: int,
    chars_done: int,
) -> Optional[List[int]]:
    """Depth-first search with memoization over symbol positions."""
    remaining_counts = (c0, c1, c2, c3, c4, c5, c6, c7)
    remaining_symbols = sum(remaining_counts)

    if idx == STEPS:
        # All symbols consumed; close the final character.
        if remaining_counts != (0, 0, 0, 0, 0, 0, 0, 0):
            return None
        if not (32 <= current_mask <= 126):
            return None
        # Check prefix constraint (including the last char).
        if chars_done < len(PREFIX):
            if current_mask != PREFIX[chars_done]:
                return None
        elif chars_done == len(PREFIX) and len(PREFIX) == chars_done:
            # All prefix chars already matched; ok.
            pass
        return []

    # If not enough slots remain to spend remaining symbols, prune.
    if remaining_symbols > (STEPS - idx):
        return None

    counts_list = [c0, c1, c2, c3, c4, c5, c6, c7]
    for sym in ADVANCING[idx]:
        if counts_list[sym] == 0:
            continue

        next_counts = counts_list.copy()
        next_counts[sym] -= 1

        # Extend or start a character depending on ordering.
        if prev == -1 or sym >= prev:
            new_mask = current_mask | (1 << sym)
            res = dfs(
                idx + 1,
                *next_counts,
                sym,
                new_mask,
                chars_done,
            )
            if res is not None:
                return [sym] + res
        else:
            # Close current char; it must be printable and respect prefix if needed.
            if not (32 <= current_mask <= 126):
                continue
            if chars_done < len(PREFIX) and current_mask != PREFIX[chars_done]:
                continue
            new_mask = 1 << sym
            res = dfs(
                idx + 1,
                *next_counts,
                sym,
                new_mask,
                chars_done + 1,
            )
            if res is not None:
                return [sym] + res

    return None


def reconstruct_string(bits: List[int]) -> str:
    chars: List[int] = []
    prev = -1
    mask = 0
    for b in bits:
        if prev != -1 and b < prev:
            chars.append(mask)
            mask = 0
        mask |= 1 << b
        prev = b
    chars.append(mask)
    return "".join(chr(c) for c in chars)


def main() -> None:
    solution_bits = dfs(0, *COUNTS, -1, 0, 0)
    if solution_bits is None:
        raise SystemExit("No solution found")
    beat = reconstruct_string(solution_bits)
    print(beat)


if __name__ == "__main__":
    main()
